/**
 * @provenance
 * Source Repository: https://github.com/guillaumehussong/standard-vocal-mcp
 * Original File: standard-vocal-mcp-main/src/server.ts
 * License: MIT
 * Adapted by: ForgeAI Studio Builder for ai-voice-agent
