/**
 * @provenance
 * Source Repository: https://github.com/RiyanshiVerma-11/Vocalis-AI
 * Original File: Vocalis-AI-main/src/components/CandidateStageTile.tsx
 * License: MIT
 * Adapted by: ForgeAI Studio Builder for ai-voice-agent
